#include <vector>
#include <numeric>
#include <algorithm>
using namespace std;

class Solution {
public:
    vector<int> hitBricks(vector<vector<int>>& grid, vector<vector<int>>& hits) {
        int m = grid.size(), n = grid[0].size();
        int roof = m * n;
        int k = hits.size();

        vector<vector<int>> remaining = grid;
        vector<bool> removed(k, false);

        for (int i = 0; i < k; ++i) {
            int r = hits[i][0], c = hits[i][1];
            if (remaining[r][c] == 1) {
                removed[i] = true;
                remaining[r][c] = 0;
            }
        }

        vector<int> parent(roof + 1), size(roof + 1, 1);
        iota(parent.begin(), parent.end(), 0);

        auto find = [&](int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        };

        auto unite = [&](int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return;
            if (size[a] < size[b]) swap(a, b);
            parent[b] = a;
            size[a] += size[b];
        };

        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (remaining[r][c] == 0) continue;

                int id = r * n + c;
                if (r == 0) unite(id, roof);
                if (r > 0 && remaining[r - 1][c] == 1)
                    unite(id, (r - 1) * n + c);
                if (c > 0 && remaining[r][c - 1] == 1)
                    unite(id, r * n + c - 1);
            }
        }

        vector<int> result(k, 0);
        const int dr[] = {-1, 1, 0, 0};
        const int dc[] = {0, 0, -1, 1};

        for (int i = k - 1; i >= 0; --i) {
            if (!removed[i]) continue;

            int before = size[find(roof)];
            int r = hits[i][0], c = hits[i][1];
            int id = r * n + c;

            remaining[r][c] = 1;
            if (r == 0) unite(id, roof);

            for (int d = 0; d < 4; ++d) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n &&
                    remaining[nr][nc] == 1) {
                    unite(id, nr * n + nc);
                }
            }

            int after = size[find(roof)];
            result[i] = max(0, after - before - 1);
        }

        return result;
    }
};

